const rows = $input.first().json.rows;
const projectId = rows[0].project_id;

const characters = [];
const locations = [];
const scenes = [];

// Deduplicate characters and locations
const charIds = new Set();
const locIds = new Set();
const seenScenes = new Set();

for (const row of rows) {
  if (row.char_id && !charIds.has(row.char_id)) {
    charIds.add(row.char_id);
    characters.push({ name: row.char_name, role: row.char_role, description: row.char_desc });
  }
  if (row.loc_id && !locIds.has(row.loc_id)) {
    locIds.add(row.loc_id);
    locations.push({ name: row.loc_name, type: row.loc_type, description: row.loc_desc });
  }
  if (row.scene_summary && !seenScenes.has(row.scene_summary)) {
    seenScenes.add(row.scene_summary);
    scenes.push({ summary: row.scene_summary, location: row.scene_location, emotional_tone: row.emotional_tone, time_period: row.time_period });
  }
}

const intel = JSON.parse(rows[0].intelligence_data || '{}');

return [{
  json: {
    project_id: projectId,
    title: rows[0].title,
    author: rows[0].author,
    language: rows[0].language,
    characters: characters,
    locations: locations,
    scenes: scenes,
    themes: intel.themes || [],
    narrative_structure: intel.narrative_structure || {}
  }
}];

const storyRaw = $('Execute Logic (LLM)').item.json.response || '{}';
const styleRaw = $('Execute Logic (Style)').item.json.response || '{}';
const timelineRaw = $('Execute Logic (Timeline)').item.json.response || '{}';

let storyBible = {}, styleBible = {}, timelineBible = {};

try {
  const storyMatch = storyRaw.match(/\{[\s\S]*\}/);
  if (storyMatch) storyBible = JSON.parse(storyMatch[0]);
} catch(e) { storyBible = { error: 'Parse failed' }; }

try {
  const styleMatch = styleRaw.match(/\{[\s\S]*\}/);
  if (styleMatch) styleBible = JSON.parse(styleMatch[0]);
} catch(e) { styleBible = { error: 'Parse failed' }; }

try {
  const timelineMatch = timelineRaw.match(/\{[\s\S]*\}/);
  if (timelineMatch) timelineBible = JSON.parse(timelineMatch[0]);
} catch(e) { timelineBible = { error: 'Parse failed' }; }

const projectId = $('Execute Logic').item.json.project_id;

return [{
  json: {
    project_id: projectId,
    story_bible: storyBible,
    style_bible: styleBible,
    timeline_bible: timelineBible,
    all_bibles_locked: true
  }
}];
